            {"YouTube subscriptions could not be synchronized: {0}",new[]{"Не вдалося синхронізувати підписки YouTube: {0}","Не удалось синхронизировать подписки YouTube: {0}"}},
            {"YouTube recommendations are unavailable for this session: {0}",new[]{"Рекомендації YouTube недоступні для цієї сесії: {0}","Рекомендации YouTube недоступны для этой сессии: {0}"}},
