        static L(){Language="en";}
        public static IEnumerable<string> Keys { get { return catalog.Keys; } }
        public static string Get(string key,string language) {
            string[] pair;
            if(!catalog.TryGetValue(key,out pair))return key;
            return language=="ru"?pair[1]:language=="uk"?pair[0]:key;
        }
        public static string T(string key,params object[] args) {
            string value=Get(key,Language);
            return args.Length==0?value:String.Format(CultureInfo.CurrentCulture,value,args);
        }
        public static string Relocalize(string value) {
            if(value==null)return null;
            if(catalog.ContainsKey(value))return T(value);
            foreach(var pair in catalog)if(pair.Value[0]==value || pair.Value[1]==value)return T(pair.Key);
            return value;
        }
        public static void Set(string language) {
            Language=language=="uk" || language=="ru"?language:"en";
            var changed=Changed;if(changed!=null)changed();
        }
    }
